import json, os, glob

base = '/home/ubuntu/.agent-ml-research-idea_gen_0519_2/projects/cert_manip_resist_eval/scoring/results/plan001/individual_scores/'
files = glob.glob(os.path.join(base, '*.json'))

results = {}
for f in sorted(files):
    name = os.path.basename(f).replace('.json','')
    parts = name.split('__')
    if len(parts) == 3:
        model, ds, cond = parts
    else:
        continue
    with open(f) as fh:
        d = json.load(fh)

    if model not in results:
        results[model] = {}

    key = f'{ds}__{cond}'
    if cond == 'clean':
        results[model][key] = {'acc': d.get('accuracy'), 'errors': d.get('n_errors',0)}
    else:
        results[model][key] = {'asr': d.get('asr'), 'errors': d.get('n_errors',0)}

# Print summary table
